{
  "name": "@groundtrack/hooks",
  "version": "0.1.36",
  "description": "Lifecycle hook utilities for Groundtrack MCP clients.",
  "keywords": [
    "claude-code",
    "codex",
    "cursor",
    "groundtrack",
    "hooks",
    "mcp",
    "opencode"
  ],
  "license": "MIT",
  "bin": {
    "groundtrack": "./dist/groundtrack.js",
    "groundtrack-hook": "./dist/groundtrack-hook.js"
  },
  "files": [
    "native/",
    "dist/",
    "templates/",
    "skills/",
    "src/agents.ts",
    "README.md",
    "LICENSE"
  ],
  "type": "module",
  "exports": {
    ".": "./dist/enrich-store-event.js",
    "./enrich": {
      "types": "./dist/enrich-store-event.d.ts",
      "default": "./dist/enrich-store-event.js"
    },
    "./agent-instructions": {
      "types": "./dist/agent-instructions.d.ts",
      "default": "./dist/agent-instructions.js"
    },
    "./package.json": "./package.json",
    "./agents": {
      "types": "./src/agents.ts",
      "browser": "./src/agents.ts",
      "workerd": "./src/agents.ts",
      "development": "./src/agents.ts",
      "default": "./dist/agents.js"
    },
    "./session-import/redaction": {
      "types": "./src/session-import/redaction.ts",
      "browser": "./src/session-import/redaction.ts",
      "workerd": "./src/session-import/redaction.ts",
      "development": "./src/session-import/redaction.ts",
      "default": "./dist/session-import/redaction.js"
    },
    "./session-import/codex": {
      "types": "./src/session-import/codex.ts",
      "browser": "./src/session-import/codex.ts",
      "workerd": "./src/session-import/codex.ts",
      "development": "./src/session-import/codex.ts",
      "default": "./dist/session-import/codex.js"
    },
    "./session-import/canonical": {
      "types": "./src/session-import/canonical.ts",
      "browser": "./src/session-import/canonical.ts",
      "workerd": "./src/session-import/canonical.ts",
      "development": "./src/session-import/canonical.ts",
      "default": "./dist/session-import/canonical.js"
    },
    "./session-import/claude": {
      "types": "./src/session-import/claude.ts",
      "browser": "./src/session-import/claude.ts",
      "workerd": "./src/session-import/claude.ts",
      "development": "./src/session-import/claude.ts",
      "default": "./dist/session-import/claude.js"
    },
    "./session-import/opencode": {
      "types": "./src/session-import/opencode.ts",
      "browser": "./src/session-import/opencode.ts",
      "workerd": "./src/session-import/opencode.ts",
      "development": "./src/session-import/opencode.ts",
      "default": "./dist/session-import/opencode.js"
    },
    "./session-import/normalize": {
      "types": "./src/session-import/normalize.ts",
      "browser": "./src/session-import/normalize.ts",
      "workerd": "./src/session-import/normalize.ts",
      "development": "./src/session-import/normalize.ts",
      "default": "./dist/session-import/normalize.js"
    },
    "./session-import/prune": {
      "types": "./src/session-import/prune.ts",
      "development": "./src/session-import/prune.ts",
      "default": "./dist/session-import/prune.js"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "fixtures:session-import": "tsx scripts/make-session-fixtures.ts",
    "lint": "vp lint",
    "prepack": "pnpm run build",
    "release:patch": "node scripts/release-patch.mjs",
    "sync:agent-instructions": "node scripts/sync-agent-instructions.mjs",
    "test": "pnpm run build && node --import tsx --test test/*.test.ts",
    "typecheck": "tsc -p tsconfig.json --noEmit && tsc -p tsconfig.test.json"
  },
  "dependencies": {
    "@clack/prompts": "0.11.0",
    "jsonc-parser": "3.3.1",
    "toml-eslint-parser": "0.10.0"
  },
  "devDependencies": {
    "@groundtrack/typescript": "workspace:*",
    "@types/node": "^25.9.1",
    "tsx": "^4.20.5",
    "typescript": "~7.0.2"
  },
  "engines": {
    "node": ">=22.19"
  }
}
